import { Context, Data, Effect, Ref } from 'effect';
/** Typed error raised when a command accesses a managed resource that is not currently acquired. */
export class ResourceNotAvailable extends Data.TaggedError('ResourceNotAvailable') {
}
const ManagedResourceTypeId = Symbol.for('@foldkit/ManagedResource');
/** Creates a managed resource identity with a `.get` accessor for use in commands. */
export const tag = () => (key) => {
    const serviceTag = Context.Service(`@foldkit/ManagedResource/${key}`);
    const get = Effect.gen(function* () {
        const ref = yield* serviceTag;
        const maybeValue = yield* Ref.get(ref);
        return yield* Effect.fromOption(maybeValue);
    }).pipe(Effect.catchTag('NoSuchElementError', () => Effect.fail(new ResourceNotAvailable({ resource: key }))));
    return {
        [ManagedResourceTypeId]: ManagedResourceTypeId,
        key,
        get,
        _tag: serviceTag,
    };
};
